const sum=rows.reduce((s,r)=>s+r.i,0);
let cum=0; const shares=rows.map((r,idx)=>{const raw=(r.i/sum)*100; const share=Math.round(raw*10)/10; return r;});
// recalc with last adjust
let shares2=[]; cum=0;
for(let i=0;i<rows.length;i++){let share=Math.round((rows[i].i/sum)*1000)/10; if(i===rows.length-1) share=Math.round((100-cum)*10)/10; else cum=Math.round((cum+share)*10)/10; shares2.push({...rows[i],share,cum: i===rows.length-1?100:cum});}
const hhi=Math.round(shares2.reduce((s,r)=>s+r.share*r.share,0));
const top3=Math.round(shares2.slice(0,3).reduce((s,r)=>s+r.share,0)*10)/10;
const excess=rows.map(r=>({c:r.c,e:Math.round((r.i-11)*10)/10}));
const es=excess.reduce((s,r)=>s+r.e,0);
let ec=0; const eShares=excess.map((r,i)=>{let share=Math.round((r.e/es)*1000)/10; if(i===excess.length-1) share=Math.round((100-ec)*10)/10; else ec=Math.round((ec+share)*10)/10; return {...r,share};});
const dsum=rows.reduce((s,r)=>s+r.x,0);
const drank=[...rows].sort((a,b)=>b.x-a.x);
let dc=0; const dShares=drank.map((r,i)=>{let share=Math.round((r.x/dsum)*1000)/10; if(i===drank.length-1) share=Math.round((100-dc)*10)/10; else dc=Math.round((dc+share)*10)/10; return {c:r.c,share,x:r.x};});
console.log({sum,shares2,top3,hhi,eShares,dShares,w:Math.round(dsum/rows.reduce((s,r)=>s+r.r,0)*1000)/10});
"

