"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  BENCHMARKS,
  CONCENTRATION_PATH,
  EXCESS_SLICES,
  HEADLINE,
  PERIMETER_COMPARE,
  SOURCE_NOTE,
  SOURCES,
  VINTAGE_LABELS,
  concentrationCurve,
  concentrationMetrics,
  fmtBn,
  fmtHhi,
  fmtPct,
  shareLadder,
  sustainabilityScatter,
  type IntensityVintageKey,
  type MetricMode,
} from "@/data/ai-capex-intensity-concentration-2026q3-data";

// viz-types: Lorenz area+line, ranked intensity bars, excess donut, path multi-line, perimeter compare bars, intensity-FCF scatter | layout: default

type ViewId = "ladder" | "path" | "excess" | "sustainability";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
